const icons={chat:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H5l-3 2V11.5a9.5 9.5 0 0 1 19 0Z"/><path d="M7 9h9M7 13h6"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Zm6-2v16m6-14v16"/>',dice:'<rect x="3" y="3" width="18" height="18" rx="4"/><path d="M7.5 7.5h.01M16.5 7.5h.01M12 12h.01M7.5 16.5h.01M16.5 16.5h.01" stroke-width="3"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',cube:'<path d="m12 2 9 5v10l-9 5-9-5V7l9-5Z"/><path d="m3 7 9 5 9-5M12 12v10M7.5 4.5l9 5v10"/>',spark:'<path d="m12 3 2.8 6.2L21 12l-6.2 2.8L12 21l-2.8-6.2L3 12l6.2-2.8L12 3Z"/><path d="m20 2 .7 1.3L22 4l-1.3.7L20 6l-.7-1.3L18 4l1.3-.7L20 2Z"/>',network:'<rect x="8" y="8" width="8" height="8" rx="2"/><rect x="1" y="1" width="5" height="5" rx="1"/><rect x="18" y="1" width="5" height="5" rx="1"/><rect x="1" y="18" width="5" height="5" rx="1"/><rect x="18" y="18" width="5" height="5" rx="1"/><path d="m6 6 3 3m6 0 3-3m-3 9 3 3m-9-3-3 3"/>',database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',book:'<path d="M3 3h7a2 2 0 0 1 2 2v16a4 4 0 0 0-4-2H3V3Zm18 0h-7a2 2 0 0 0-2 2v16a4 4 0 0 1 4-2h5V3Z"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',key:'<circle cx="8" cy="8" r="5"/><path d="m11.5 11.5 9 9m-3-3 2.5-2.5M7 7h.01"/>',sliders:'<path d="M4 3v5m0 5v8M12 3v10m0 5v3M20 3v2m0 5v11"/><circle cx="4" cy="10.5" r="2.5"/><circle cx="12" cy="15.5" r="2.5"/><circle cx="20" cy="7.5" r="2.5"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v4a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-4"/>',upload:'<path d="M12 16V4m-4 4 4-4 4 4M4 15v5a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',check:'<path d="m5 12 4 4L19 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',file:'<path d="M14 2H5a1 1 0 0 0-1 1v18a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1V8l-6-6Z"/><path d="M14 2v6h6M8 13h8M8 17h6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H4a1 1 0 0 0-1 1v16a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-6"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',server:'<rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6.5h.01M7 17.5h.01M11 6.5h6M11 17.5h6"/>',gift:'<path d="M3 10h18v4H3zM5 14v7h14v-7M12 10v11"/><path d="M12 10C3 10 5 1 9 4c2 2 3 6 3 6Zm0 0c9 0 7-9 3-6-2 2-3 6-3 6Z"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M10 5h4M11 19h2"/>',monitor:'<rect x="2" y="3" width="20" height="14" rx="2"/><path d="M8 21h8m-4-4v4"/>',edit:'<path d="m15 5 4 4M3 21l5-1 13-13-4-4L4 16l-1 5Z"/>',plus:'<path d="M12 5v14M5 12h14"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.file}</svg>`;
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=(s)=>{try{const u=new URL(String(s||''),location.origin);return ['https:','http:'].includes(u.protocol)?u.href:'#';}catch{return '#';}};
const $=(q,root=document)=>root.querySelector(q);const $$=(q,root=document)=>[...root.querySelectorAll(q)];
const state={session:null,datasets:[],models:[],jobs:[],catalog:null,model:null,dataset:null,installPrompt:null};
const route=location.pathname.replace(/\/$/,'')||'/';
const routeNames={'/orders':'Project orders','/chat':'Central chat','/':'The entrance','/workspace':'Workspace','/linkers':'Linkers','/cloud':'Cloud','/future-work':'Future work','/games':'Kuzey Marmara games','/synthesis':'MRI synthesis','/federated':'Federated lab','/datasets':'Datasets','/research':'Research journal','/vault':'The vault','/red-room':'Red room','/admin':'Administration','/download':'Install web app'};
const main=$('#vx-main');
const signin=(path=route)=>`/signin-with-chatgpt?return_to=${encodeURIComponent(path)}`;
const isAccount=()=>state.session?.user?.kind==='account';
const toast=(message,error=false)=>{const el=document.createElement('div');el.className='vx-toast'+(error?' error':'');el.textContent=message;$('#vx-toast-region').append(el);setTimeout(()=>el.remove(),6500);};
async function api(path,options={}){const headers={...(options.body&&!(options.body instanceof Blob)?{'Content-Type':'application/json'}:{}),...options.headers};const response=await fetch(path,{credentials:'same-origin',...options,headers,body:options.body&&!(options.body instanceof Blob)?JSON.stringify(options.body):options.body});let result={};try{result=await response.json();}catch{throw new Error('The server returned an unexpected response. Please try again.');}if(!response.ok){const err=new Error(result.error?.message||result.message||'The request could not be completed.');err.code=result.error?.code;err.status=response.status;throw err;}return result;}
async function busy(button,fn,label='Working…'){const text=button.innerHTML;button.disabled=true;button.innerHTML=esc(label);try{return await fn();}catch(error){toast(error.message,true);return null;}finally{button.disabled=false;button.innerHTML=text;}}
function download(text,filename,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function dateLabel(value){if(!value)return 'This session';const d=new Date(value);return Number.isNaN(d.getTime())?'This session':d.toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});}
const pill=(text,kind='')=>`<span class="vx-chip ${kind?'vx-chip-'+kind:''}">${esc(text)}</span>`;
const note=(text,kind='')=>`<div class="vx-note ${kind?'vx-note-'+kind:''}">${icon('info')}<p>${text}</p></div>`;
const empty=(title,desc,ico='file')=>`<div class="vx-empty">${icon(ico)}<h3>${esc(title)}</h3><p>${esc(desc)}</p></div>`;
const heading=(kicker,title,description,actions='')=>`<div class="vx-page-heading"><div><div class="vx-kicker">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${actions?`<div class="vx-heading-actions">${actions}</div>`:''}</div>`;
const linkButton=(href,text,ico='',secondary=false)=>`<a class="vx-button ${secondary?'vx-secondary':''}" href="${esc(href)}">${ico?icon(ico):''}${esc(text)}</a>`;
function dsName(ds){return ds.name||ds.label||ds.title||ds.id;}function dsModality(ds){return ds.modality||(dsOwn(ds)?'Unspecified':(/-t1ce$/.test(ds.id)?'T1ce':/-flair$/.test(ds.id)?'FLAIR':/-t2$/.test(ds.id)?'T2':'T1'));}function dsOwn(ds){return ds.private||ds.kind==='upload'||ds.kind==='uploaded'||ds.kind==='saved-sample'||ds.kind==='private'||ds.source==='upload'||ds.isPrivate||ds.ownerId||ds.storage==='private';}function dsSynthetic(ds){return /demo-00|phantom|synthetic/i.test([ds.id,ds.name,ds.source,ds.kind].join(' '));}
function dsThumb(ds,large=false){if(dsOwn(ds))return '';return dsSynthetic(ds)?(large?'/assets/phantom-preview.png':`/assets/phantom-${/002/.test(ds.id)?'2':'1'}-thumb.png`):(large?'/assets/mni-preview.png':'/assets/mni-thumb.png');}
function dsViewer(ds){return ds.viewerUrl||(`/viewer.html?sample=${encodeURIComponent(/002/.test(ds.id)?'demo-002':dsSynthetic(ds)?'demo-001':'mni152')}&modality=${encodeURIComponent(dsModality(ds))}`);}
function dsDownload(ds){return ds.downloadUrl||ds.url||`/api/datasets/${encodeURIComponent(ds.id)}/download`;}
function modelName(model){return model.name||model.title||'Paired pGAN';}function modelSource(model){return model.source||model.sourceModality||(/t2-t1/.test(model.id)?'T2':'T1');}function modelTarget(model){return model.target||model.targetModality||(/flair/.test(model.id)?'FLAIR':/t2-t1/.test(model.id)?'T1':'T2');}
async function loadDatasets(){const data=await api('/api/datasets');state.datasets=data.datasets||data.items||[];return state.datasets;}
async function loadModels(){const data=await api('/api/models');state.models=data.models||data.items||[];return state.models;}
async function loadJobs(){const data=await api('/api/jobs');state.jobs=data.jobs||data.items||[];return state.jobs;}
async function loadCatalog(){if(state.catalog)return state.catalog;const response=await fetch('/research-catalog.json');if(!response.ok)throw new Error('The research catalog is temporarily unavailable.');state.catalog=await response.json();return state.catalog;}
function refreshSessionUI(){const user=state.session?.user;$('#vx-credit-total').textContent=user?.credits??'—';$('#vx-side-name').textContent=user?.kind==='account'?(user.name||'Research account'):'Student workspace';$('#vx-side-kind').textContent=user?.kind==='account'?(user.memberId||'Signed in · Private collection'):'Open research · Demo edition';const account=$('#vx-account');account.href=isAccount()?'/vault':signin();account.innerHTML=`${esc(isAccount()?(user.name||'My account'):'Sign in')}${icon('user')}`;}
function requireAccountCard(title,description,ico='lock'){return `<div class="vx-gate vx-panel"><div class="vx-gate-art"><div class="vx-gate-symbol">${icon(ico)}</div></div><div class="vx-gate-body"><div class="vx-kicker">MEMBER ACCESS</div><h2>${esc(title)}</h2><p>${esc(description)}</p><a class="vx-button" href="${signin()}" target="_top">${icon('user')}Sign in with ChatGPT</a>${note('Public datasets, the MRI explorer, and the research journal stay available without an account.','neutral')}</div></div>`;}
function jobsHTML(){return state.jobs.length?state.jobs.slice(0,8).map(job=>`<div class="vx-job"><div><div class="vx-job-title">${esc(job.modelName||job.label||job.modelId||'MRI synthesis demo')}</div><div class="vx-job-meta">${esc(dateLabel(job.createdAt))} · ${esc(job.datasetName||job.datasetId||'Built-in study')} · Precomputed demonstration</div></div><div class="vx-job-actions">${pill(job.status==='completed'?'READY':job.status||'READY')}${job.viewerUrl?`<a class="vx-button vx-secondary vx-small-button" href="${esc(safeUrl(job.viewerUrl))}">${icon('eye')}View</a>`:''}${job.outputUrl?`<a class="vx-button vx-ghost vx-small-button" href="${esc(safeUrl(job.outputUrl))}" download>${icon('download')}Output</a>`:''}</div></div>`).join(''):empty('No demo jobs yet','Choose a model and a built-in study to explore the synthesis workflow.','spark');}
async function home(){const results=await Promise.allSettled([loadDatasets(),loadModels(),loadJobs(),loadCatalog()]);const pubs=state.catalog?.publications||state.catalog?.papers||[];const studies=[...new Map(state.datasets.filter(d=>!dsOwn(d)).map(d=>[(d.studyId||(/002/.test(d.id)?'demo-002':dsSynthetic(d)?'demo-001':'mni152')),d])).values()];main.innerHTML=heading('YOUR RESEARCH, CONNECTED','Explore. Experiment. Understand.','A shared workspace for medical imaging, generative models, and collaborative research.',linkButton('/viewer.html','Open MRI explorer','cube'))+`<div class="vx-stats-grid">${[{label:'Built-in studies',num:studies.length||'—',detail:'Reference anatomy + synthetic phantoms',ico:'database'},{label:'Synthesis workflows',num:state.models.length||'—',detail:'Precomputed demonstration workflows',ico:'spark'},{label:'Research publications',num:pubs.length||'—',detail:'Source-linked research journal',ico:'book'},{label:'Available demo credits',num:state.session?.user?.credits??'—',detail:'Explore the synthesis workflow',ico:'gift'}].map(s=>`<div class="vx-stat"><div class="vx-stat-label">${s.label}</div><div class="vx-stat-number">${s.num}</div><div class="vx-stat-detail">${s.detail}</div><span class="vx-stat-icon">${icon(s.ico)}</span></div>`).join('')}</div><div class="vx-home-grid"><section class="vx-panel vx-explorer-feature"><div class="vx-feature-top"><h2>See beyond a single slice.</h2>${pill('3D + MULTIPLANAR','blue')}</div><img class="vx-feature-preview" src="/assets/mni-preview.png" alt="Axial, coronal, and sagittal MRI reference anatomy"/><div class="vx-feature-bottom"><p><strong>Your window into the volume.</strong>Rotate a 3D scan, navigate linked slices, and compare imaging modalities.</p>${linkButton('/viewer.html','Explore anatomy','cube')}</div></section><div class="vx-workflow-stack"><a class="vx-panel vx-workflow-card" href="/synthesis"><h3>${icon('spark')}MRI synthesis</h3><p>Choose a model workflow and explore a source-to-target modality demonstration.</p><div class="vx-link-line"><span>Open synthesis workspace</span><span>3 workflows</span></div></a><a class="vx-panel vx-workflow-card" href="/federated"><h3>${icon('network')}Federated lab</h3><p>Compose a distributed experiment. Choose datasets, clients, and an aggregation strategy.</p><div class="vx-link-line"><span>Configure an experiment</span><span>YAML export</span></div></a></div></div><div class="vx-section-heading"><h2>Start with a study</h2><a class="vx-text-link" href="/datasets">Browse all datasets</a></div><div class="vx-study-grid">${studies.slice(0,3).map(ds=>`<a class="vx-panel vx-study-card" href="${esc(dsViewer(ds))}"><img src="${esc(dsThumb(ds))}" alt="${esc(dsName(ds))} MRI thumbnail"/><div><h3>${esc(dsSynthetic(ds)?`Synthetic study ${/002/.test(ds.id)?'002':'001'}`:'Reference anatomy')}</h3><p>${dsSynthetic(ds)?'4 modalities · 128 × 128 × 128':'MNI reference · T1-weighted'}</p>${pill(dsSynthetic(ds)?'SYNTHETIC PHANTOM':'REFERENCE DATA',dsSynthetic(ds)?'amber':'blue')}</div></a>`).join('')||empty('Sample catalog is loading','Use the MRI explorer to open the built-in reference volume.','database')}</div><div class="vx-section-heading"><h2>Recent synthesis activity</h2><a class="vx-text-link" href="/synthesis">Synthesis workspace</a></div><div class="vx-panel vx-job-list">${jobsHTML()}</div>${note('This is a working web preview. Synthesis uses precomputed examples; federated experiments export configurations. Real model inference and remote training are not connected.','neutral')}`;}
async function synthesis(){await Promise.all([loadModels(),loadDatasets(),loadJobs()]);state.model=state.models[0];main.innerHTML=heading('GENERATIVE IMAGING','MRI synthesis workspace','Explore modality-to-modality synthesis with a selected model workflow.',`${pill('PRECOMPUTED DEMO','amber')}<button class="vx-button vx-secondary vx-small-button" id="vx-mint-credits" type="button">${icon('plus')}Generate 100 demo credits</button>`)+note('<strong>Workflow demonstration.</strong> These cards describe intended model integrations. Running a demo retrieves a precomputed synthetic target volume; no model weights or inference service are connected.','amber')+`<div class="vx-two-col"><form class="vx-panel" id="vx-synthesis-form"><div class="vx-form-section"><div class="vx-step-label">MODEL SELECTION</div><h3>Choose a synthesis workflow</h3><div class="vx-model-grid" id="vx-model-grid">${state.models.map((m,i)=>`<button type="button" class="vx-model-card ${i===0?'active':''}" data-model="${esc(m.id)}"><span class="vx-selected-check"></span><span class="vx-model-name">${esc(modelName(m))}</span><span class="vx-model-pair">${esc(modelSource(m))}${icon('chevron')}${esc(modelTarget(m))}</span><span class="vx-model-detail">MODEL WORKFLOW</span></button>`).join('')}</div></div><div class="vx-form-section"><div class="vx-step-label">INPUT VOLUME</div><h3>Select a study</h3><div class="vx-field"><label for="vx-synthesis-dataset">Source dataset</label><select id="vx-synthesis-dataset" class="vx-select" required></select><small>Built-in synthetic studies support the precomputed demonstration. Private uploads need a real inference backend.</small></div></div><div class="vx-form-section"><div class="vx-form-footer"><div><strong class="vx-cost-label" id="vx-cost-label">${state.model?.costCredits??'—'} demo credits per completed job</strong><p class="vx-inline-info">Available: <span id="vx-local-credits">${state.session?.user?.credits??'—'}</span> demo credits · no monetary value</p></div><button class="vx-button" type="submit" id="vx-run-demo">${icon('spark')}Run demo workflow</button></div><div class="vx-inline-status" id="vx-synth-status" role="status"></div></div></form><aside class="vx-panel vx-preview-card" id="vx-input-preview"></aside></div><section class="vx-panel vx-code-panel"><div class="vx-panel-header"><div><div class="vx-kicker">YOUR SELECTED WORKFLOW</div><h2>Take the code with you.</h2><p>A runnable Python demo and JSON configuration for your current selection.</p></div><div class="vx-flex"><button class="vx-button vx-secondary" id="vx-download-code" type="button">${icon('download')}Python code</button><button class="vx-button vx-ghost" id="vx-download-config" type="button">Configuration</button></div></div><details class="vx-code-details"><summary>Preview the Python demo</summary><pre id="vx-code-preview" tabindex="0"></pre></details><p class="vx-code-note">The script downloads the selected synthetic input and prepared target. A marked integration point is included for a future trained model.</p></section><div class="vx-section-heading"><h2>Job history</h2><button type="button" class="vx-button vx-ghost vx-small-button" id="vx-refresh-jobs">${icon('clock')}Refresh</button></div><div class="vx-panel vx-job-list" id="vx-jobs">${jobsHTML()}</div>`;function updateInput(){const matching=state.datasets.filter(d=>dsSynthetic(d)&&!dsOwn(d)&&String(dsModality(d)).toLowerCase()===String(modelSource(state.model)).toLowerCase());$('#vx-cost-label').textContent=`${state.model.costCredits} demo credits per completed job`;const select=$('#vx-synthesis-dataset');select.innerHTML=matching.map(d=>`<option value="${esc(d.id)}">${esc(dsName(d))}${dsOwn(d)?' · Private upload':''}</option>`).join('');state.dataset=matching[0];updatePreview();}function updatePreview(){const ds=state.dataset;if(!ds){$('#vx-input-preview').innerHTML=empty('No matching source volume','Choose another workflow or browse the dataset catalog.','database');return;}$('#vx-input-preview').innerHTML=`<div><div class="vx-kicker">INPUT PREVIEW</div><h3>${esc(dsName(ds))}</h3></div>${dsThumb(ds,true)?`<img src="${esc(dsThumb(ds,true))}" alt="Input study preview"/>`:`<div class="vx-empty">${icon('file')}<p>Private volume</p></div>`}<dl class="vx-data-list"><div><dt>Source modality</dt><dd>${esc(dsModality(ds))}</dd></div><div><dt>Target modality</dt><dd>${esc(modelTarget(state.model))}</dd></div><div><dt>Data type</dt><dd>${dsOwn(ds)?'Private upload':dsSynthetic(ds)?'Synthetic phantom':'Reference anatomy'}</dd></div><div><dt>Execution</dt><dd>Precomputed demonstration</dd></div></dl><p class="vx-inline-info">Outputs illustrate the interface and download workflow. They are not predictions and are not suitable for clinical use.</p>`;const preview=$('#vx-code-preview');if(preview)preview.textContent=workflowCode(state.model,state.dataset,location.origin).code;}$$('[data-model]').forEach(btn=>btn.addEventListener('click',()=>{state.model=state.models.find(m=>m.id===btn.dataset.model);$$('[data-model]').forEach(b=>b.classList.toggle('active',b===btn));updateInput();}));$('#vx-synthesis-dataset').addEventListener('change',e=>{state.dataset=state.datasets.find(d=>d.id===e.target.value);updatePreview();});$('#vx-synthesis-form').addEventListener('submit',e=>{e.preventDefault();if(!state.model||!state.dataset)return;busy($('#vx-run-demo'),async()=>{const result=await api('/api/synthesis',{method:'POST',body:{modelId:state.model.id,datasetId:state.dataset.id,requestKey:crypto.randomUUID()}});if(result.credits!==undefined){state.session.user.credits=result.credits;refreshSessionUI();$('#vx-local-credits').textContent=result.credits;}await loadJobs();$('#vx-jobs').innerHTML=jobsHTML();$('#vx-synth-status').textContent='Precomputed demo output is ready in your job history.';toast('Demo output is ready. You can view or download the precomputed volume.');},'Preparing demo…');});$('#vx-refresh-jobs').addEventListener('click',e=>busy(e.currentTarget,async()=>{await loadJobs();$('#vx-jobs').innerHTML=jobsHTML();toast('Job history refreshed.');},'Refreshing…'));$('#vx-mint-credits').addEventListener('click',e=>busy(e.currentTarget,async()=>{const result=await api('/api/credits/mint',{method:'POST',body:{}});state.session.user.credits=result.credits;refreshSessionUI();$('#vx-local-credits').textContent=result.credits;toast(result.awardedCredits?`${result.awardedCredits} imaginary demo credits added.`:'Your demo balance is already at its limit.');},'Generating…'));$('#vx-download-code').addEventListener('click',()=>{if(state.model&&state.dataset)download(workflowCode(state.model,state.dataset,location.origin).code,`voxel-${state.model.id}-demo.py`,'text/x-python');});$('#vx-download-config').addEventListener('click',()=>{if(state.model&&state.dataset)download(JSON.stringify(workflowCode(state.model,state.dataset,location.origin).config,null,2),`voxel-${state.model.id}-workflow.json`,'application/json');});updateInput();}
async function datasets(){await loadDatasets();main.innerHTML=heading('DATA LIBRARY','Your imaging datasets','Browse reference anatomy, explore synthetic studies, or keep your own NIfTI files in a private collection.',linkButton('/viewer.html','Open MRI explorer','cube',true))+`<div class="vx-upload-zone" id="vx-upload-zone"><div class="vx-upload-info">${icon('upload')}<div><h3>Bring your own MRI volume</h3><p>NIfTI .nii or .nii.gz · 32 MiB per file · 64 MiB account storage · ${isAccount()?'Private to your signed-in account':'Sign in to store and download your own files'}</p></div></div><input type="file" id="vx-file-input" accept=".nii,.gz" hidden/>${isAccount()?`<button class="vx-button" id="vx-upload-button">${icon('upload')}Choose MRI file</button>`:`<a class="vx-button" href="${signin()}" target="_top">${icon('user')}Sign in to upload</a>`}</div><div class="vx-filter-bar"><div class="vx-search-wrap">${icon('search')}<input class="vx-input" id="vx-dataset-search" placeholder="Search datasets or modalities…" aria-label="Search datasets"/></div><select class="vx-select" id="vx-dataset-filter" aria-label="Dataset type"><option value="all">All datasets</option><option value="builtin">Built-in samples</option><option value="private">My private files</option></select><select class="vx-select" id="vx-modality-filter" aria-label="Modality"><option value="all">All modalities</option><option>T1</option><option>T1ce</option><option>T2</option><option>FLAIR</option></select></div><div class="vx-dataset-grid" id="vx-dataset-grid"></div>${note('Reference anatomy and synthetic phantoms are labeled separately. No real patient database is connected to this preview. Local files can also be opened directly in the MRI explorer.','neutral')}`;function render(){const q=$('#vx-dataset-search').value.toLowerCase();const f=$('#vx-dataset-filter').value;const mod=$('#vx-modality-filter').value;const rows=state.datasets.filter(d=>(dsName(d)+' '+dsModality(d)).toLowerCase().includes(q)&&(f==='all'||(f==='private')===Boolean(dsOwn(d)))&&(mod==='all'||dsModality(d).toLowerCase()===mod.toLowerCase()));$('#vx-dataset-grid').innerHTML=rows.length?rows.map(ds=>`<article class="vx-panel vx-dataset-card"><div class="vx-dataset-image">${dsThumb(ds,true)?`<img src="${esc(dsThumb(ds,true))}" alt="${esc(dsName(ds))} preview"/>`:`<span class="vx-dataset-icon">${icon('file')}</span>`}</div><div class="vx-panel-inner"><div>${pill(dsOwn(ds)?'PRIVATE FILE':dsSynthetic(ds)?'SYNTHETIC PHANTOM':'REFERENCE ANATOMY',dsOwn(ds)?'':dsSynthetic(ds)?'amber':'blue')}</div><h3>${esc(dsName(ds))}</h3><p>${esc(ds.description||(dsOwn(ds)?'Your private NIfTI volume, stored with your account.':dsSynthetic(ds)?'Invented geometry for comparing imaging contrasts and demonstrating a region overlay.':'An openly accessible reference MRI for exploring anatomy in 2D and 3D.'))}</p><div class="vx-tag-row"><span class="vx-tag">${esc(dsModality(ds))}</span><span class="vx-tag">NIfTI</span>${dsSynthetic(ds)?'<span class="vx-tag">128³ · 1.5 mm</span>':''}</div><div class="vx-dataset-card-actions">${(!dsOwn(ds)||ds.viewerUrl)?`<a class="vx-button vx-secondary vx-small-button" href="${esc(dsViewer(ds))}">${icon('eye')}Explore</a>`:''}<a class="vx-button vx-ghost vx-small-button" href="${esc(safeUrl(dsDownload(ds)))}" download>${icon('download')}Download</a>${!dsOwn(ds)?`<button class="vx-button vx-ghost vx-small-button" data-import="${esc(ds.id)}">${icon('plus')}Save</button>`:''}</div></div></article>`).join(''):empty('No datasets match','Try another search or upload a NIfTI file to your private collection.','database');$$('[data-import]').forEach(b=>b.addEventListener('click',()=>{if(!isAccount()){location.href=signin();return;}busy(b,async()=>{await api('/api/datasets/import',{method:'POST',body:{sampleId:b.dataset.import}});await loadDatasets();render();toast('Sample saved to your private collection.');},'Saving…');}));}$('#vx-dataset-search').addEventListener('input',render);$('#vx-dataset-filter').addEventListener('change',render);$('#vx-modality-filter').addEventListener('change',render);async function upload(file){if(!file)return;if(file.size>(state.session?.storage?.maxFileBytes||33554432)){toast('The file is too large. Choose a volume up to 32 MiB or open it locally in the MRI explorer.',true);return;}if(!/\.nii(\.gz)?$/i.test(file.name)){toast('Choose a NIfTI file ending in .nii or .nii.gz.',true);return;}const b=$('#vx-upload-button');await busy(b,async()=>{await api(`/api/datasets/upload?name=${encodeURIComponent(file.name)}`,{method:'POST',body:file,headers:{'Content-Type':'application/octet-stream'}});await loadDatasets();render();toast('MRI file saved to your private collection.');},'Uploading…');}if(isAccount()){$('#vx-upload-button').addEventListener('click',()=>$('#vx-file-input').click());$('#vx-file-input').addEventListener('change',e=>upload(e.target.files[0]));const zone=$('#vx-upload-zone');zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragover');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragover'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragover');upload(e.dataTransfer.files[0]);});}render();}
async function federated(){await loadDatasets();let lastConfig=null;main.innerHTML=heading('COLLABORATIVE LEARNING','Federated experiment lab','Design a multi-client learning configuration and export it for your research environment.',`${pill('CONFIGURATION WORKSPACE','blue')}${linkButton('/datasets','Manage datasets','database',true)}${linkButton('/orders#10','Documentation roadmap','book',true)}`)+`<div class="vx-two-col"><form class="vx-panel" id="vx-federated-form"><div class="vx-form-section"><div class="vx-step-label">DATA SOURCES</div><h3>Choose participant datasets</h3><div class="vx-collection-list">${state.datasets.map((d,i)=>`<label class="vx-check-row"><input type="checkbox" name="datasets" value="${esc(d.id)}" ${i===0?'checked':''}/><span>${esc(dsName(d))}<small>${esc(dsModality(d))} · ${dsOwn(d)?'Private collection':dsSynthetic(d)?'Synthetic demonstration':'Reference anatomy'}</small></span></label>`).join('')}</div></div><div class="vx-form-section"><div class="vx-step-label">TRAINING CONFIGURATION</div><h3>Define the experiment</h3><div class="vx-form-grid"><div class="vx-field"><label for="vx-aggregation">Aggregation strategy</label><select class="vx-select" id="vx-aggregation"><option>FedAvg</option><option>FedAdam</option><option>FedNova</option><option>FedProx</option></select></div><div class="vx-field"><label for="vx-clients">Number of clients</label><input class="vx-input" type="number" id="vx-clients" value="4" min="2" max="20" required/></div><div class="vx-field"><label for="vx-rounds">Communication rounds</label><input class="vx-input" type="number" id="vx-rounds" value="100" min="1" max="1000" required/></div><div class="vx-field"><label for="vx-local-epochs">Local epochs per round</label><input class="vx-input" type="number" id="vx-local-epochs" value="1" min="1" max="100" required/></div></div></div><div class="vx-form-section"><div class="vx-form-footer"><p class="vx-inline-info">Save the configuration, then download a readable YAML file.</p><button class="vx-button" id="vx-save-config" type="submit">${icon('file')}Save configuration</button></div><div id="vx-config-status" class="vx-inline-status" role="status"></div></div></form><aside><div class="vx-panel vx-panel-inner"><div class="vx-kicker">EXPERIMENT TOPOLOGY</div><h3>Local learning. Shared updates.</h3><div class="vx-topology"><div class="vx-central-node">${icon('server')}Aggregator</div>${[1,2,3,4].map(()=>`<span class="vx-client-node">${icon('database')}</span>`).join('')}</div><dl class="vx-data-list"><div><dt>Strategy</dt><dd id="vx-strategy-preview">FedAvg</dd></div><div><dt>Configured clients</dt><dd id="vx-client-preview">4</dd></div><div><dt>Rounds × local epochs</dt><dd id="vx-round-preview">100 × 1</dd></div><div><dt>Execution</dt><dd>Configuration only</dd></div></dl>${note('This diagram illustrates a federation. No clients are connected and saving does not launch training.','neutral')}</div><div class="vx-panel vx-panel-inner vx-mt-20" id="vx-config-output"><h3>Configuration export</h3>${empty('Your YAML will appear here','Set the experiment parameters and save a configuration.','file')}</div></aside></div>`;function preview(){$('#vx-strategy-preview').textContent=$('#vx-aggregation').value;$('#vx-client-preview').textContent=$('#vx-clients').value;$('#vx-round-preview').textContent=`${$('#vx-rounds').value} × ${$('#vx-local-epochs').value}`;}['#vx-aggregation','#vx-clients','#vx-rounds','#vx-local-epochs'].forEach(id=>$(id).addEventListener('input',preview));$('#vx-federated-form').addEventListener('submit',e=>{e.preventDefault();const datasetIds=$$('input[name=datasets]:checked').map(i=>i.value);if(!datasetIds.length){toast('Select at least one dataset for the configuration.',true);return;}const body={datasetIds,aggregation:$('#vx-aggregation').value,clients:Number($('#vx-clients').value),rounds:Number($('#vx-rounds').value),localEpochs:Number($('#vx-local-epochs').value)};busy($('#vx-save-config'),async()=>{const result=await api('/api/federated/config',{method:'POST',body});lastConfig=result.config||result;const yaml=lastConfig.yaml||`# Voxel Atlas federated configuration\n# Configuration only; no training has been executed.\naggregation: ${body.aggregation}\nclients: ${body.clients}\nrounds: ${body.rounds}\nlocal_epochs: ${body.localEpochs}\ndatasets:\n${body.datasetIds.map(x=>'  - '+JSON.stringify(x)).join('\n')}\n`;$('#vx-config-output').innerHTML=`<h3>Configuration saved</h3><pre class="vx-code-box">${esc(yaml)}</pre><button class="vx-button vx-secondary" id="vx-download-config">${icon('download')}Download YAML</button>`;$('#vx-download-config').addEventListener('click',()=>download(yaml,`voxel-atlas-${body.aggregation.toLowerCase()}-config.yaml`,'application/yaml'));$('#vx-config-status').textContent='Your experiment configuration is saved. Training has not been started.';toast('Federated configuration saved. YAML export is ready.');},'Saving…');});}
function authorNames(paper){return (paper.authors||[]).map(a=>typeof a==='string'?a:a.name).join(', ');}
function citation(paper){return paper.bibtex||`@article{${String(paper.id||'voxelatlas').replace(/[^a-zA-Z0-9]/g,'')},\n  title = {${paper.title||''}},\n  author = {${(paper.authors||[]).map(a=>typeof a==='string'?a:a.name).join(' and ')}},\n  year = {${paper.year||''}},\n  doi = {${paper.doi||''}},\n  url = {${paper.url||''}}\n}\n`;}
async function research(){const cat=await loadCatalog();const people=cat.people||cat.collaborators||cat.authors||[];const papers=cat.publications||cat.papers||[];const topics=[...new Set(papers.flatMap(p=>p.tags||[p.topic].filter(Boolean)))].sort();main.innerHTML=heading('PEOPLE & PUBLICATIONS','Research journal','A curated collection of work across medical imaging, federated learning, and data science.',`<a class="vx-button vx-secondary" href="/selected-publications.bib" download>${icon('download')}Export citations</a>`)+`<div class="vx-section-heading"><h2>The research network</h2><span class="vx-chip vx-chip-muted">${people.length} CONTRIBUTORS</span></div><div class="vx-people-grid">${people.map(p=>`<article class="vx-panel vx-person"><span class="vx-person-avatar">${esc(p.initials||p.name.split(' ').map(n=>n[0]).filter(Boolean).slice(0,2).join(''))}</span><div><h3>${esc(p.name)}</h3><p>${esc(p.affiliation||p.role||'Research collaborator')}</p><div class="vx-person-links">${p.profileUrl?`<a href="${esc(safeUrl(p.profileUrl))}" target="_blank" rel="noopener noreferrer">Profile</a>`:''}${p.scholarUrl?`<a href="${esc(safeUrl(p.scholarUrl))}" target="_blank" rel="noopener noreferrer">Google Scholar</a>`:''}<button class="vx-tab" data-person-filter="${esc(p.id)}" style="font-size:.68rem;padding:3px 7px">Publications</button></div></div></article>`).join('')}</div><div class="vx-section-heading"><h2>Selected publications</h2><span id="vx-paper-count" class="vx-chip vx-chip-muted">${papers.length} WORKS</span></div><div class="vx-filter-bar"><div class="vx-search-wrap">${icon('search')}<input class="vx-input" id="vx-paper-search" placeholder="Search titles, authors, or keywords…" aria-label="Search publications"/></div><select id="vx-author-filter" class="vx-select" aria-label="Filter by author"><option value="all">All contributors</option>${people.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select><select id="vx-topic-filter" class="vx-select" aria-label="Filter by topic"><option value="all">All topics</option>${topics.map(t=>`<option>${esc(t)}</option>`).join('')}</select></div><div class="vx-paper-list" id="vx-paper-list"></div>${note(esc(cat.coverageNote||'This selected collection is not a complete Google Scholar import and is not automatically synchronized.'),'neutral')}`;function render(){const q=$('#vx-paper-search').value.toLowerCase(),author=$('#vx-author-filter').value,topic=$('#vx-topic-filter').value;const rows=papers.filter(p=>([p.title,authorNames(p),p.venue,...(p.tags||[])].join(' ').toLowerCase().includes(q))&&(author==='all'||(p.authors||[]).some(a=>a.id===author))&&(topic==='all'||(p.tags||[]).includes(topic)||p.topic===topic));$('#vx-paper-count').textContent=`${rows.length} ${rows.length===1?'WORK':'WORKS'}`;$('#vx-paper-list').innerHTML=rows.length?rows.map(p=>{const verified=p.verification?.status==='verified';const sources=p.verification?.sources||p.sourceUrls||[];return `<article class="vx-panel vx-paper"><div class="vx-paper-top"><div class="vx-tag-row">${pill(p.type||'Publication','muted')}${pill(verified?'SOURCE VERIFIED':'PARTIALLY VERIFIED',verified?'':'amber')}</div><span class="vx-paper-year">${esc(p.year||'')}</span></div><h3>${esc(p.title)}</h3><p class="vx-paper-authors">${esc(authorNames(p))}</p><p class="vx-paper-venue">${esc(p.venue||'')}${p.pages?' · pp. '+esc(p.pages):''}</p>${p.summary?`<p class="vx-paper-summary">${esc(p.summary)}</p>`:''}${!verified&&p.verification?.notes?`<div class="vx-verification-note">${esc(p.verification.notes)}</div>`:''}<div class="vx-paper-bottom"><div class="vx-tag-row">${(p.tags||[]).map(t=>`<span class="vx-tag">${esc(t)}</span>`).join('')}</div><div class="vx-paper-links">${p.url?`<a class="vx-button vx-secondary vx-small-button" href="${esc(safeUrl(p.url))}" target="_blank" rel="noopener noreferrer">${icon('external')}Source</a>`:''}<button class="vx-button vx-ghost vx-small-button" data-cite="${esc(p.id)}">${icon('download')}BibTeX</button><button class="vx-button vx-ghost vx-small-button" data-evidence="${esc(p.id)}">${icon('info')}Verification</button></div></div></article>`;}).join(''):empty('No matching publications','Try a different keyword, author, or research topic.','book');$$('[data-cite]').forEach(b=>b.addEventListener('click',()=>{const p=papers.find(p=>p.id===b.dataset.cite);download(citation(p),`${p.id||'citation'}.bib`,'application/x-bibtex');}));$$('[data-evidence]').forEach(b=>b.addEventListener('click',()=>{const p=papers.find(p=>p.id===b.dataset.evidence);const sources=p.verification?.sources||p.sourceUrls||[];$('#vx-dialog-content').innerHTML=`<h2>Source verification</h2><p>${esc(p.verification?.notes||'See the linked source for publication details.')}</p><div class="vx-data-list">${sources.map(s=>{const href=typeof s==='string'?s:s.url;return `<a class="vx-text-link" target="_blank" rel="noopener noreferrer" href="${esc(safeUrl(href))}">${esc(typeof s==='string'?new URL(s).hostname:s.title||s.url)}</a>`;}).join('')}</div>`;$('#vx-dialog').showModal();}));}$('#vx-paper-search').addEventListener('input',render);$('#vx-author-filter').addEventListener('change',render);$('#vx-topic-filter').addEventListener('change',render);$$('[data-person-filter]').forEach(b=>b.addEventListener('click',()=>{$('#vx-author-filter').value=b.dataset.personFilter;render();$('#vx-paper-search').scrollIntoView({behavior:'smooth',block:'center'});}));render();}
async function vault(){main.innerHTML=heading('MEMBER SPACE','The vault','A small challenge for curious minds. Solve the puzzle to unlock a one-time demo reward.',linkButton('/orders#10','Policies & documents roadmap','book',true));if(!isAccount()){main.innerHTML+=requireAccountCard('Your next discovery starts here.','Sign in to access the educational puzzle and keep your reward attached to your account.','gift');return;}const result=await api('/api/vault');const puzzle=result.puzzle||{};function rewardHTML(){return `<div class="vx-gate vx-panel"><div class="vx-gate-art"><div class="vx-gate-symbol">${icon('check')}</div></div><div class="vx-gate-body"><div class="vx-kicker">REWARD CLAIMED</div><h2>A little curiosity goes a long way.</h2><div class="vx-reward-number">${result.prizeCredits||100}<small>demo credits</small></div><p>Your one-time vault reward has been added to your account. Use your available demo credits to explore synthesis workflows.</p>${linkButton('/synthesis','Explore MRI synthesis','spark')}${note('Demo credits are for this educational preview. They have no monetary value and cannot be exchanged for money.','neutral')}</div></div>`;}if(result.claimed){main.innerHTML+=rewardHTML();return;}main.innerHTML+=`<div class="vx-gate vx-panel"><div class="vx-gate-art"><div class="vx-gate-symbol">${icon('gift')}</div></div><div class="vx-gate-body"><div class="vx-kicker">ONE QUESTION · ONE DISCOVERY</div><h2>${esc(puzzle.question||'Explore the imaging challenge')}</h2><p>Answer correctly to receive ${result.prizeCredits||100} demo credits. This reward can be claimed once per account.</p><div class="vx-choice-list">${(puzzle.choices||[]).map((c,i)=>`<button class="vx-choice" data-answer="${esc(typeof c==='string'?c:c.value||c.label)}"><span class="vx-choice-letter">${String.fromCharCode(65+i)}</span>${esc(typeof c==='string'?c:c.label)}</button>`).join('')}</div><div class="vx-inline-status" id="vx-vault-status" role="status"></div>${note('Educational reward only. Demo credits have no cash value.','neutral')}</div></div>`;$$('[data-answer]').forEach(b=>b.addEventListener('click',()=>busy(b,async()=>{const response=await api('/api/vault',{method:'POST',body:{answer:b.dataset.answer}});if(response.correct===false){$('#vx-vault-status').textContent=response.message||'Not quite. Think about the left and right sides of a volume and try again.';return;}if(response.credits!==undefined){state.session.user.credits=response.credits;refreshSessionUI();}main.innerHTML=heading('MEMBER SPACE','The vault','A small challenge for curious minds.')+rewardHTML();toast(response.alreadyClaimed?'Your vault reward was already claimed.':'Correct. Your one-time demo credits have been added.');},'Checking answer…')));}
async function redRoom(){main.classList.add('vx-red-theme');main.innerHTML=heading('PRIVATE MEMBER SPACE','The red room','A separate space for invited research members.');if(!isAccount()){main.innerHTML+=requireAccountCard('A quieter place for deeper work.','The Red Room requires a signed-in account, your Voxel Atlas membership ID, and the room password.','key');return;}try{const result=await api('/api/red-room');main.innerHTML+=`<div class="vx-panel vx-panel-inner"><div class="vx-kicker">MEMBER ACCESS VERIFIED</div><h2>${esc(result.title||'Red Room')}</h2><p class="vx-inline-info">${esc(result.message||'Your private member space is open.')}</p><div class="vx-grid-2 vx-mt-20">${(result.sections||[]).map(s=>`<article class="vx-panel vx-panel-inner"><h3>${esc(s.title)}</h3><p class="vx-inline-info">${esc(s.description)}</p></article>`).join('')}</div>${note(`Membership ID: <strong>${esc(result.memberId||state.session.user.memberId)}</strong>. Room access is temporary and protected by your account and room credentials.`)}</div>`;return;}catch(error){if(![401,403,409].includes(error.status))throw error;}main.innerHTML+=`<div class="vx-gate vx-panel"><div class="vx-gate-art"><div class="vx-gate-symbol">${icon('key')}</div></div><div class="vx-gate-body"><div class="vx-kicker">INVITATION-ONLY RESEARCH LOUNGE</div><h2>Enter your member credentials.</h2><p>Use your site membership ID and the room password provided by the workspace owner.</p><form class="vx-gate-form" id="vx-room-form"><div class="vx-field"><label for="vx-member-id">Voxel Atlas membership ID</label><input class="vx-input" id="vx-member-id" value="${esc(state.session.user.memberId||'')}" autocomplete="username" required/><small>This site ID identifies your account. No government identity document is requested.</small></div><div class="vx-field"><label for="vx-room-password">Room password</label><input class="vx-input" id="vx-room-password" type="password" autocomplete="current-password" required/></div><button class="vx-button" type="submit" id="vx-room-submit">${icon('key')}Unlock the red room</button><div id="vx-room-status" class="vx-inline-status" role="status"></div></form></div></div>`;$('#vx-room-form').addEventListener('submit',e=>{e.preventDefault();busy($('#vx-room-submit'),async()=>{await api('/api/red-room/unlock',{method:'POST',body:{memberId:$('#vx-member-id').value.trim(),password:$('#vx-room-password').value}});toast('Member access verified. Your private room is open.');await redRoom();},'Verifying access…');});}
async function admin(){main.innerHTML=heading('OWNER WORKSPACE','Administration','Manage private research drafts and member-space access.');if(!isAccount()){main.innerHTML+=requireAccountCard('Workspace administration','Sign in with the site owner account to manage private projects and administration settings.','sliders');return;}if(!state.session.user.isOwner){main.innerHTML+=`<div class="vx-gate vx-panel"><div class="vx-gate-art"><div class="vx-gate-symbol">${icon('lock')}</div></div><div class="vx-gate-body"><h2>Owner access required.</h2><p>This account can use the student workspace. Administration is available only to the site owner.</p>${linkButton('/','Return to workspace','home',true)}</div></div>`;return;}if(!state.session.user.adminUnlocked){const setup=!state.session.adminKeyConfigured;main.innerHTML+=`<div class="vx-gate vx-panel"><div class="vx-gate-art"><div class="vx-gate-symbol">${icon('sliders')}</div></div><div class="vx-gate-body"><div class="vx-kicker">OWNER IDENTITY CONFIRMED</div><h2>${setup?'Create your administration key.':'Unlock administration.'}</h2><p>${setup?'Set a private administration password to protect owner actions in addition to your platform sign-in.':'Enter your administration password to manage private research drafts and room settings.'}</p><form class="vx-gate-form" id="vx-admin-login"><div class="vx-field"><label for="vx-admin-password">Administration password</label><input class="vx-input" type="password" id="vx-admin-password" minlength="12" maxlength="128" autocomplete="${setup?'new-password':'current-password'}" required/><small>Use at least 12 characters.</small></div><button class="vx-button" id="vx-admin-submit" type="submit">${icon('lock')}${setup?'Create administration key':'Unlock administration'}</button></form></div></div>`;$('#vx-admin-login').addEventListener('submit',e=>{e.preventDefault();busy($('#vx-admin-submit'),async()=>{await api(setup?'/api/admin/key':'/api/admin/login',{method:'POST',body:{password:$('#vx-admin-password').value}});state.session=await api('/api/session');refreshSessionUI();await admin();toast(setup?'Administration key created. Owner workspace is unlocked.':'Owner workspace unlocked.');},setup?'Creating key…':'Unlocking…');});return;}const [projectResponse,settings]=await Promise.all([api('/api/admin/projects'),api('/api/admin/settings')]);const projects=projectResponse.projects||[];main.innerHTML+=`<div class="vx-flex vx-mb-20">${pill('OWNER VERIFIED')}${pill('PRIVATE DRAFTS','blue')}</div><div class="vx-grid-2" id="vx-admin-projects">${projects.map(p=>`<article class="vx-panel vx-admin-project"><div class="vx-tag-row">${pill(p.status||'draft','muted')}${pill(p.kind||'research','blue')}</div><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p>${p.budgetUsd!=null?`<p class="vx-inline-info">Planning amount: ${esc(new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(p.budgetUsd))} · Private proposal only</p>`:''}<button class="vx-button vx-secondary vx-small-button" data-edit-project="${esc(p.id)}">${icon('edit')}Edit private draft</button></article>`).join('')}<article class="vx-panel vx-admin-project"><div class="vx-tag-row">${pill('NEW DRAFT','muted')}</div><h3>Start a private project</h3><p>Keep an idea, research scope, or opportunity proposal in the owner workspace.</p><button class="vx-button vx-secondary vx-small-button" id="vx-add-project">${icon('plus')}Create private draft</button></article></div><section class="vx-panel vx-mt-20"><div class="vx-panel-header"><div><h2>Red room access</h2><p>Set or replace the password for the private member space.</p></div>${pill(settings.redRoomConfigured?'PASSWORD SET':'NOT CONFIGURED',settings.redRoomConfigured?'':'amber')}</div><form id="vx-room-settings" class="vx-form-section"><div class="vx-form-grid"><div class="vx-field"><label for="vx-new-room-password">New room password</label><input class="vx-input" type="password" id="vx-new-room-password" minlength="12" maxlength="128" autocomplete="new-password" required/><small>At least 12 characters. Changing the password revokes existing room sessions.</small></div><div class="vx-field" style="justify-content:flex-end"><button class="vx-button" id="vx-room-settings-submit" type="submit">${icon('key')}Save room password</button></div></div></form></section>`;function projectEditor(project){const p=project||{};$('#vx-dialog-content').innerHTML=`<h2>${project?'Edit private draft':'Create a private draft'}</h2><p>Visible only inside the authorized owner workspace.</p><form id="vx-project-form"><div class="vx-form-grid"><div class="vx-field vx-span-2"><label for="vx-project-title">Project title</label><input id="vx-project-title" class="vx-input" maxlength="120" value="${esc(p.title||'')}" required/></div><div class="vx-field"><label for="vx-project-kind">Type</label><select class="vx-select" id="vx-project-kind"><option value="research" ${p.kind!=='opportunity'?'selected':''}>Research</option><option value="opportunity" ${p.kind==='opportunity'?'selected':''}>Opportunity draft</option></select></div><div class="vx-field"><label for="vx-project-status">Status</label><select class="vx-select" id="vx-project-status">${['draft','planned','active','archived'].map(s=>`<option value="${s}" ${s===(p.status||'draft')?'selected':''}>${s[0].toUpperCase()+s.slice(1)}</option>`).join('')}</select></div><div class="vx-field vx-span-2"><label for="vx-project-description">Description</label><textarea class="vx-textarea" id="vx-project-description" maxlength="3000" required>${esc(p.description||'')}</textarea></div><div class="vx-field"><label for="vx-project-budget">Planning amount (USD, optional)</label><input class="vx-input" id="vx-project-budget" type="number" min="0" max="1000000" step="1" value="${p.budgetUsd??''}"/></div><div class="vx-field" style="justify-content:flex-end"><button class="vx-button" type="submit" id="vx-project-save">${icon('check')}Save private draft</button></div></div></form>`;$('#vx-dialog').showModal();$('#vx-project-form').addEventListener('submit',e=>{e.preventDefault();busy($('#vx-project-save'),async()=>{const body={title:$('#vx-project-title').value.trim(),description:$('#vx-project-description').value.trim(),status:$('#vx-project-status').value,kind:$('#vx-project-kind').value,budgetUsd:$('#vx-project-budget').value===''?null:Number($('#vx-project-budget').value)};await api(project?`/api/admin/projects/${encodeURIComponent(project.id)}`:'/api/admin/projects',{method:project?'PATCH':'POST',body});$('#vx-dialog').close();await admin();toast('Private project draft saved.');},'Saving…');});}$$('[data-edit-project]').forEach(b=>b.addEventListener('click',()=>projectEditor(projects.find(p=>p.id===b.dataset.editProject))));$('#vx-add-project').addEventListener('click',()=>projectEditor(null));$('#vx-room-settings').addEventListener('submit',e=>{e.preventDefault();busy($('#vx-room-settings-submit'),async()=>{await api('/api/admin/settings',{method:'POST',body:{redRoomPassword:$('#vx-new-room-password').value}});await admin();toast('Room password saved. Previous room sessions have been revoked.');},'Saving password…');});}
function downloadPage(){main.innerHTML=heading('TAKE THE WORKSPACE WITH YOU','Install Voxel Atlas','A web app for your computer, tablet, and phone. Keep the workspace one tap away.')+`<section class="vx-panel vx-install-card"><img class="vx-app-icon" src="/assets/app-icon-192.png" alt="Voxel Atlas app icon"/><div><h2>Your research, within reach.</h2><p>Install the web app or add it to your home screen.</p></div><button class="vx-button" id="vx-install-app">${icon('download')}Install web app</button></section><div class="vx-grid-3"><section class="vx-panel vx-os-card"><h3>${icon('phone')}Android</h3><ol><li>Open Voxel Atlas in Chrome.</li><li>Tap <strong>Install web app</strong> when your browser offers installation.</li><li>Or open Chrome’s menu and choose <strong>Add to Home screen</strong> or <strong>Install app</strong>.</li></ol><small>Wording depends on your browser version. The installed app uses this same website.</small></section><section class="vx-panel vx-os-card"><h3>${icon('monitor')}macOS</h3><ol><li>On macOS Sonoma 14 or later, open Voxel Atlas in Safari.</li><li>Choose <strong>File → Add to Dock</strong>.</li><li>Confirm the name and click <strong>Add</strong>.</li></ol><small>Chrome and other supporting desktop browsers may also offer an install icon in the address bar.</small></section><section class="vx-panel vx-os-card"><h3>${icon('phone')}iPhone & iPad</h3><ol><li>Open Voxel Atlas in Safari.</li><li>Tap <strong>Share</strong>, then <strong>Add to Home Screen</strong>.</li><li>Turn on <strong>Open as Web App</strong> if shown, then tap <strong>Add</strong>.</li></ol><small>Installation is managed by Safari. Use the Share menu if an automatic install prompt is unavailable.</small></section></div>${note('Voxel Atlas is currently a web app, not a native desktop or mobile binary. Sign-in, stored data, and server actions require an internet connection. Private pages and API responses are not cached for offline use.','neutral')}<div class="vx-panel vx-panel-inner"><h3>Prefer the browser?</h3><p class="vx-inline-info">Every workspace feature remains available on the web. Installation is optional.</p><div class="vx-flex vx-mt-20">${linkButton('/','Open workspace','home',true)}${linkButton('/viewer.html','Explore an MRI','cube',true)}</div></div>`;$('#vx-install-app').addEventListener('click',async()=>{if(state.installPrompt){state.installPrompt.prompt();const choice=await state.installPrompt.userChoice;state.installPrompt=null;toast(choice.outcome==='accepted'?'Web app installation accepted.':'Installation dismissed. You can continue using the website.');}else if(window.matchMedia('(display-mode: standalone)').matches){toast('Voxel Atlas is already open as an installed web app.');}else{$('#vx-dialog-content').innerHTML='<h2>Install with your browser</h2><p>This browser has not offered an automatic install prompt. On iPhone or iPad, use Safari’s Share menu and choose Add to Home Screen. On macOS Safari, use File → Add to Dock. On Android Chrome, use its menu and choose Install app or Add to Home screen.</p>';$('#vx-dialog').showModal();}});}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();state.installPrompt=event;});window.addEventListener('appinstalled',()=>{state.installPrompt=null;toast('Voxel Atlas web app installed.');});
async function boot(){document.body.dataset.route=route.slice(1)||'entrance';$$('span[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));$$('[data-path]').forEach(el=>{if(el.dataset.path===route)el.setAttribute('aria-current','page');el.insertAdjacentHTML('afterbegin',icon(el.dataset.icon));});$('#vx-route-label').textContent=routeNames[route]||'Workspace';document.title=`${routeNames[route]||'Workspace'} · Voxel Atlas`;$('#vx-menu-toggle').addEventListener('click',()=>{$('#vx-sidebar').classList.add('open');$('#vx-scrim').hidden=false;});$('#vx-scrim').addEventListener('click',()=>{$('#vx-sidebar').classList.remove('open');$('#vx-scrim').hidden=true;});try{state.session=await api('/api/session');refreshSessionUI();}catch(error){state.session={user:{kind:'guest',name:'Guest explorer',credits:null},demo:true};refreshSessionUI();toast('Account services are temporarily unavailable. Public browsing remains available.',true);}const pages={'/orders':async()=>(await import('/orders.js')).renderOrders(main,{session:state.session,api,toast}),'/chat':async()=>(await import('/central-chat.js')).renderCentralChat(main,{session:state.session,api,toast}),'/':async()=>(await import('/journey.js')).renderEntrance(main),'/workspace':home,'/linkers':async()=>(await import('/journey.js')).renderLinkers(main),'/cloud':async()=>(await import('/journey.js')).renderCloud(main),'/future-work':async()=>(await import('/journey.js')).renderFuture(main),'/games':async()=>(await import('/games.js')).renderGames(main),'/synthesis':synthesis,'/federated':federated,'/datasets':datasets,'/research':research,'/vault':vault,'/red-room':redRoom,'/admin':admin,'/download':downloadPage};try{await(pages[route]||pages['/'])();}catch(error){main.innerHTML=`<div class="vx-error-page"><div class="vx-kicker">WORKSPACE CONNECTION</div><h2>We couldn’t load this section.</h2><p>${esc(error.message)}</p><button class="vx-button" id="vx-retry">Try again</button> ${linkButton('/viewer.html','Open MRI explorer','cube',true)}</div>`;$('#vx-retry').addEventListener('click',()=>location.reload());}if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});}
boot();
